import{XO_CONFIG as n,UNITS_TO_METRES as m}from"./config.min.js";export function jumpLift(t){const o=n.pose.jump;if(!(t>=0)||t>=1)return 0;const r=typeof o.peakAt=="number"?o.peakAt:.5,e=Math.min(.95,Math.max(.05,r)),u=t<e?.5*(t/e):.5+.5*((t-e)/(1-e));return Math.sin(Math.PI*u)*o.lift}export function spanOf(t){const o=t||{};if(!(o.startX!==void 0&&o.targetX!==void 0))return null;const r=Math.hypot(o.targetX-o.startX,o.targetY-o.startY);return r>0?{sx:o.startX,sy:o.startY,tx:o.targetX,ty:o.targetY,total:r,reach:Math.min(1,r*m/n.ball.fullArcAt)}:null}export function arcHeightAt(t,o,r){const e=n.ball,u=Math.hypot(o-t.sx,r-t.sy),a=Math.min(1,Math.max(0,u/t.total));return e.release+4*a*(1-a)*e.apex*t.reach}export function ballHeight(t){if(!t||!t.coords)return n.ball.release;const o=spanOf(t.coords);return o?arcHeightAt(o,t.coords.x,t.coords.y):n.ball.release}export function inTheAir(t){return t>=0&&t<n.pose.jump.hang}export function handsAt(t,o){const r=o/n.pose.jump.hang;return t+jumpLift(r)}export function leapCatches(t,o,r){return inTheAir(o)?typeof t!="number"?!0:r<=handsAt(t,o)+n.pose.jump.manual.slack:!1}export function arrivalIn(t,o,r){if(!t||!o||!t.coords||!o.coords)return 1/0;const e=r||0,u=o.coords.x,a=o.coords.y;if(Math.hypot(u-t.coords.x,a-t.coords.y)<=e)return 0;const p=Array.isArray(t.coords.list)?t.coords.list:[],h=o.state&&o.state.xSpeed||0,l=o.state&&o.state.ySpeed||0;for(let c=0;c<p.length;c+=1){const f=p[c],i=c+1;if(Math.hypot(u+h*i-f[0],a+l*i-f[1])<=e)return i/n.simHz}return 1/0}export function cueLit(t,o,r){return arrivalIn(t,o,r)<=n.pose.jump.manual.cueLead}let s=null;export function autoJump(){if(s===null){s=!1;try{const t=localStorage.getItem(n.storage.jump);t&&(s=JSON.parse(t).auto===!0)}catch{}}return s}export function setAutoJump(t){s=!!t;try{localStorage.setItem(n.storage.jump,JSON.stringify({auto:s}))}catch{}return s}export function resetAutoJump(){s=null}
